H.rgo2=()=>{if(RM.m!=='manual'){const r=resolveAct();if(!r)return;TM.start(RM.m,r.a.id,r.sid,+val('rdm'));RM.pre='';save();return render()}
 const d=readD(val('rd'));if(!d)return toast('تاریخ نامعتبر است',1);let st=val('r1'),e2=val('r2'),m=+val('r3'),min;
 if(st&&e2){if(st===e2)return toast('زمان شروع و پایان برابر است',1);min=dur(st,e2)}else if(st&&m>0){min=m;e2=hm(tm(st)+m)}else if(m>0){min=m;e2=nowHM();st=hm(tm(e2)-m)}else return toast('شروع و پایان، یا فقط مدت را وارد کنید',1);
 const ov=E(d).filter(x=>tm(st)<tm(x.start)+x.min&&tm(x.start)<tm(st)+min);if(ov.length&&!confirm('این بازه با '+fa(ov.length)+' ثبت دیگر هم‌پوشانی دارد. با این حال ثبت شود؟'))return;
 const r=resolveAct();if(!r)return;if(db.entries.some(x=>x.date===d&&x.start===st&&x.actId===r.a.id&&x.min===min))return toast('این ثبت دقیقاً تکراری است',1);
 db.entries.push({id:uid(),date:d,actId:r.a.id,subId:r.sid,start:st,end:e2,min,note:val('rn'),cut:val('rcut'),src:'manual'});RM.pre='';save();toast('ثبت شد: '+mm(min));render()};
