 timeline:{n:'خط زمانی',cols:'g2',order:['cap','tl','rec','logs','time'],full:['tl','rec','logs']},
 calendar:{n:'تقویم در اولویت',cols:'g2',order:['week','dlc','top','rec','logs'],full:['week','rec','logs']},
 goals:{n:'اهداف در اولویت',cols:'g2',order:['goals','top','rec','logs','dist'],full:['rec','logs']},
