function logCards(d){const l=E(d).sort((a,b)=>a.start.localeCompare(b.start));return l.length?'<div class="g g3">'+l.map(e=>`<div class="c alc" style="border-inline-start:4px solid ${aC(e.actId)}"><b>${esc(aN(e.actId))}</b> <span class="m">${esc(subN(e.actId,e.subId))}</span><div class="alt">${mm(e.min)}</div><div class="m"><bdi dir="ltr">${fT(e.start)}–${fT(e.end)}</bdi></div>${e.note?'<div class="m">'+esc(e.note)+'</div>':''}${alBtns(e)}</div>`).join('')+'</div>':'<p class="m">ثبتی برای این روز نیست.</p>'}
function logTL(d){const l=E(d).sort((a,b)=>a.start.localeCompare(b.start));return l.length?'<div class="tlr">'+l.map(e=>`<div class="tli" style="--tc:${aC(e.actId)}"><span class="tlt"><bdi dir="ltr">${fT(e.start)}</bdi></span><div class="tlb"><b>${esc(aN(e.actId))}</b> <span class="m">${esc(subN(e.actId,e.subId))} · ${mm(e.min)}</span>${e.note?'<div class="m">'+esc(e.note)+'</div>':''}${alBtns(e)}</div></div>`).join('')+'</div>':'<p class="m">ثبتی برای این روز نیست.</p>'}
const wkIso=t=>t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');
function weekStrip(d){const t=new Date(d+'T12:00:00'),st=new Date(t);st.setDate(t.getDate()-(t.getDay()+1)%7);const days=[...Array(7)].map((_,i)=>{const x=new Date(st);x.setDate(st.getDate()+i);return wkIso(x)}),mins=days.map(x=>sumU(E(x))),mx=Math.max(1,...mins),N=['ش','ی','د','س','چ','پ','ج'];return'<div class="c"><h3>هفته‌ی من</h3><div class="wk">'+days.map((x,i)=>`<div class="wkd ${x===d?'on':''}"><small>${N[i]}</small><i style="height:${Math.max(3,Math.round(mins[i]/mx*54))}px"></i><b>${fa(+x.slice(8))}</b><span>${mins[i]?mm(mins[i]):'—'}</span></div>`).join('')+'</div></div>'}
const cwList=()=>Array.isArray(db.set.cw)&&db.set.cw.length?db.set.cw.filter(k=>ALLK.includes(k)):DLAY.full.order.slice();
function cwEditor(){const cw=cwList(),off=ALLK.filter(k=>!cw.includes(k));return'<div class="cwe">'+cw.map(k=>`<div class="cwr"><span>${CK_N[k]}</span><button data-a="dcw" data-k="${k}" data-m="up">▲</button><button data-a="dcw" data-k="${k}" data-m="dn">▼</button>${k==='rec'||k==='logs'?'':`<button class="d" data-a="dcw" data-k="${k}" data-m="off">✕</button>`}</div>`).join('')+(off.length?'<div class="m">افزودن به داشبورد:</div><div class="row">'+off.map(k=>`<button class="chip" data-a="dcw" data-k="${k}" data-m="on">+ ${CK_N[k]}</button>`).join('')+'</div>':'')+'</div>'}
