H.pra=()=>{const a=val('pr-a'),g=+val('pr-g')||0,f=val('pr-f')==='days'?'days':'daily',dow=[...document.querySelectorAll('#pr-d input:checked')].map(i=>+i.value).filter(i=>i>=0&&i<=6);if(!act(a))return toast('فعالیت را انتخاب کن',1);if(f==='days'&&!dow.length)return toast('حداقل یک روز هفته را انتخاب کن',1);const l=Array.isArray(db.set.prec)?db.set.prec:[];if(l.length>=30)return toast('حداکثر ۳۰ کار تکرارشونده',1);l.push({id:uid(),actId:a,goal:g,freq:f,dow:f==='days'?dow:[],on:true,last:''});db.set.prec=l;if(save())render()};
