function plRecur(){const t=todayISO(),dw=new Date(t+'T12:00:00').getDay();let ch=false;(Array.isArray(db.set.prec)?db.set.prec:[]).forEach(r=>{if(!r||r.on===false||r.last===t||!act(r.actId))return;r.last=t;ch=true;if(r.freq==='daily'||(Array.isArray(r.dow)&&r.dow.includes(dw))){const arr=db.plans[t]=db.plans[t]||[];if(!arr.some(x=>x.rid===r.id))arr.push({id:uid(),actId:r.actId,start:'',end:'',goal:+r.goal||0,status:'todo',reason:'',rid:r.id})}});if(ch)save()}
function sumU(l){const by={};l.forEach(e=>{const k=e.date||'';(by[k]=by[k]||[]).push([tm(e.start),tm(e.start)+e.min])});let t=0;Object.values(by).forEach(a=>{a.sort((x,y)=>x[0]-y[0]);let s0=null,en=null;a.forEach(([x,y])=>{if(s0===null){s0=x;en=y}else if(x<=en){en=Math.max(en,y)}else{t+=en-s0;s0=x;en=y}});if(s0!==null)t+=en-s0});return t}
