function ckRate(d){const p=prog(d);return p.n?p.pc:null}
function ckWeek(ws,upto){let rs=[],mn=0;for(let i=0;i<7;i++){const d=addD(ws,i);if(d>upto)break;const r=ckRate(d);if(r!=null)rs.push(r);mn+=sumU(E(d))}return{avg:rs.length?Math.round(rs.reduce((a,b)=>a+b,0)/rs.length):null,days:rs.length,min:mn}}
