 const ws=addD(t,-((new Date(t+'T12:00:00').getDay()+1)%7)),tw=ckWeek(ws,t),lw=ckWeek(addD(ws,-7),addD(ws,-1)),a7=avg(rates.slice(6,13)),lwd=ckRate(addD(t,-7)),td=rates[13],yd=rates[12];
