H.ckmv=e=>{const d=todayISO(),x=ckFind(e.dataset.id);if(x&&plCarry(d,x.id,addD(d,1))){toast('به فردا منتقل شد؛ سابقه می‌ماند');render()}};
H.cka=()=>{const n=S_(val('ck-n'),60).trim(),g=+val('ck-g')||0;if(!n)return toast('نام کار را بنویس',1);let a=db.acts.find(x=>x.name===n);if(!a){a={id:uid(),name:n,cat:'personal',color:CATS.personal[1],tags:[],prio:'',goalDay:0,goalWeek:0,subs:[],desc:'',active:true,arch:false,days:[]};db.acts.push(a);toast('فعالیت جدید ساخته شد؛ ویژگی‌هایش را در «فعالیت‌ها» ویرایش کن')}const d=todayISO();(db.plans[d]=db.plans[d]||[]).push({id:uid(),actId:a.id,start:'',end:'',goal:g,status:'todo',reason:''});if(save())render()};
H.cklog=e=>{const d=todayISO(),x=ckFind(e.dataset.id);if(!x)return;const g=+x.goal||0,left=g?Math.max(0,g-actual(d,x.actId)):0;let min=Math.min(240,Math.max(5,Math.round((left||g||25)/5)*5));const en=nowHM(),st=hm(tm(en)-min);if(tm(en)-min<0)return toast('این ثبت از نیمه‌شب می‌گذرد؛ از «ثبت دستی» استفاده کن',1);
 const ov=E(d).filter(z=>tm(st)<tm(z.start)+z.min&&tm(z.start)<tm(st)+min);if(ov.length&&!confirm('این بازه با '+fa(ov.length)+' ثبت دیگر هم‌پوشانی دارد. با این حال ثبت شود؟'))return;
 db.entries.push({id:uid(),date:d,actId:x.actId,subId:'',start:st,end:en,min,note:'ثبت سریع از خانه',src:'quick'});if(g&&actual(d,x.actId)>=g&&x.status!=='done'){x.status='done';x.reason=''}else if(x.status==='todo')x.status='doing';if(save()){toast('ثبت شد: '+mm(min)+(x.status==='done'?' · هدف کار کامل شد ✓':''));render()}};

/* ===== DANI v1: planner priority + search/filter, and a 30-day trend line ===== */
function plPass(x){const f=zMS.pl,q=(f.q||'').trim().toLowerCase();return(!q||aN(x.actId).toLowerCase().includes(q)||(x.reason||'').toLowerCase().includes(q))&&(!f.st||x.status===f.st)&&(!f.pr||(f.pr==='high'?x.pr==='high':x.pr!=='high'))}
function plFilterBar(){const f=zMS.pl;return'<div class="mrow np"><input id="plq" data-mi="pl:q" class="grow" value="'+esc(f.q)+'" placeholder="جست‌وجو در برنامه‌ی این روز"><select data-mc="pl:fst"><option value="">همه‌ی وضعیت‌ها</option>'+PL_ST.map(z=>'<option value="'+z[0]+'" '+(f.st===z[0]?'selected':'')+'>'+z[1]+'</option>').join('')+'</select><select data-mc="pl:fpr"><option value="">همه‌ی اولویت‌ها</option><option value="high" '+(f.pr==='high'?'selected':'')+'>★ اولویت بالا</option><option value="norm" '+(f.pr==='norm'?'selected':'')+'>عادی</option></select>'+((f.q||f.st||f.pr)?mBtn('pl:clr','پاک‌کردن فیلتر',''):'')+'</div>'}
H.ppr=e=>{const x=plan(vd)[+e.dataset.i];if(x){x.pr=x.pr==='high'?'':'high';if(save())render()}};
function ckTrend(){const t=todayISO(),N=30,ok=+db.set.okRate||80,days=[...Array(N)].map((_,i)=>addD(t,i-N+1)),r=days.map(ckRate);if(r.filter(x=>x!=null).length<3)return'<p class="m">برای نمودار روند، حداقل برنامه‌ی ۳ روز لازم است.</p>';
 const W=300,Hh=90,px=i=>6+i*(W-12)/(N-1),py=v=>Hh-8-(Math.max(0,Math.min(100,v))/100)*(Hh-16),pts=[];r.forEach((v,i)=>{if(v!=null)pts.push([i,v])});
 const path=pts.map(([i,v],k)=>(k?'L':'M')+px(i).toFixed(1)+' '+py(v).toFixed(1)).join(' '),ma=[];for(let i=0;i<N;i++){const w=r.slice(Math.max(0,i-6),i+1).filter(x=>x!=null);if(w.length)ma.push([i,w.reduce((a,b)=>a+b,0)/w.length])}
 const mp=ma.map(([i,v],k)=>(k?'L':'M')+px(i).toFixed(1)+' '+py(v).toFixed(1)).join(' '),dots=pts.map(([i,v])=>'<circle cx="'+px(i).toFixed(1)+'" cy="'+py(v).toFixed(1)+'" r="2.4" fill="'+(v>=ok?'#34d399':v>=ok/2?'#f59e0b':'#ef4444')+'"/>').join('');
 return'<div class="m" style="margin-top:12px">روند ۳۰ روز</div><svg class="cmtr" viewBox="0 0 300 90" preserveAspectRatio="none" role="img" aria-label="روند درصد انجام‌شدن برنامه"><line x1="6" x2="294" y1="'+py(ok).toFixed(1)+'" y2="'+py(ok).toFixed(1)+'" stroke="currentColor" stroke-opacity=".4" stroke-dasharray="4 3"/><path d="'+path+'" fill="none" stroke="currentColor" stroke-opacity=".35" stroke-width="1.2"/><path d="'+mp+'" fill="none" stroke="var(--ac)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>'+dots+'</svg><div class="m cmleg"><span>● هر روز</span><span style="color:var(--ac)">━ میانگین ۷ روز</span><span>┅ حد موفقیت</span></div>'}

/* ===== DANI v1: Icon Studio (style + size, independent of the theme) and a background mood for every page ===== */
function icPick(S){const k=db.set.icst;return k&&SK_ICW[k]?k:S.ic}
function icScale(){return Math.min(1.5,Math.max(.8,+db.set.icsz||1))}
const IC_ST=[['','مطابق تم'],['line','خطی'],['bold','پررنگ'],['duo','دورنگ']],IC_SZ=[[.9,'کوچک'],[1,'معمولی'],[1.25,'بزرگ'],[1.4,'خیلی بزرگ']];
function iconStudio(){const cs=db.set.icst||'',sz=icScale();return'<div class="stsec"><div class="m" style="margin-top:12px"><b>'+BH('Icon Studio','استودیوی آیکون')+'</b></div><div class="row">'+IC_ST.map(x=>'<button class="chip '+(cs===x[0]?'on':'')+'" data-a="icst" data-k="'+x[0]+'">'+x[1]+'</button>').join('')+'</div><div class="row">'+IC_SZ.map(x=>'<button class="chip '+(Math.abs(sz-x[0])<.01?'on':'')+'" data-a="icsz" data-v="'+x[0]+'">'+x[1]+'</button>').join('')+'</div><div class="row icprev">'+['home','dl','acd','hab','qt','set'].map(k=>icon(k)).join('')+'</div><div class="m"><button data-a="icst" data-k="" >بازنشانی آیکون‌ها</button></div></div>'}
H.icst=e=>{const k=e.dataset.k;if(k===''||SK_ICW[k]){if(k==='')delete db.set.icst,delete db.set.icsz;else db.set.icst=k;if(save()){render()}}};
H.icsz=e=>{const v=+e.dataset.v;if(v>=.8&&v<=1.5){db.set.icsz=v;if(save())render()}};
const PG_BG=[['','بدون'],['aurora','شفق'],['dawn','سپیده'],['ocean','اقیانوس'],['forest','جنگل'],['rose','گل‌سرخ'],['mono','خاکستری']],PG_N=[['home','خانه'],['dash','میزکار'],['res','تحلیل'],['dl','موعدها'],['hab','عادت‌ها'],['rem','یادآوری‌ها'],['qt','جمله‌ها'],['acd','آکادمی'],['set','تنظیمات']];
function pgBgApply(){const m=db.set.pgbg||{},v=m[page];if(v&&PG_BG.some(x=>x[0]===v))document.documentElement.setAttribute('data-pgbg',v);else document.documentElement.removeAttribute('data-pgbg')}
function pgBgStudio(){const m=db.set.pgbg||{};return'<div class="stsec"><div class="m" style="margin-top:12px"><b>'+BH('Page Moods','حال‌وهوای هر صفحه')+'</b></div><p class="m">برای هر صفحه یک لایه‌ی رنگیِ ملایم انتخاب کن؛ داده و تم عوض نمی‌شوند.</p><div class="pgbgs">'+PG_N.map(x=>'<label class="pgb"><span>'+x[1]+'</span><select data-mc="pg:bg:'+x[0]+'">'+PG_BG.map(o=>'<option value="'+o[0]+'" '+((m[x[0]]||'')===o[0]?'selected':'')+'>'+o[1]+'</option>').join('')+'</select></label>').join('')+'</div><div class="m"><button data-a="pgreset">همه را بدون پس‌زمینه کن</button></div></div>'}
H.pgreset=()=>{delete db.set.pgbg;if(save())render()};

function errCard(){let l=[];try{l=window.daniErrs().slice(-5).reverse()}catch(e){}return'<div class="c" id="errcard"><h3>'+BH('Error Report','گزارش خطا')+'</h3>'+(l.length?'<p class="m">اگر چیزی خراب شد، این متن را برای پشتیبانی بفرست:</p>'+l.map(x=>'<div class="m" style="direction:ltr;text-align:left">'+esc(x.t)+' · '+esc(x.m)+(x.l?' (line '+esc(x.l)+')':'')+'</div>').join('')+'<div class="row" style="margin-top:8px"><button class="p" data-a="errcopy">کپی همه‌ی خطاها</button><button data-a="errclr">پاک‌کردن</button></div>':'<p class="hst ok">تا حالا خطایی ثبت نشده ✓</p>')+'</div>'}
H.errcopy=()=>{const t=(window.daniErrText&&window.daniErrText())||'';try{navigator.clipboard.writeText(t).then(()=>toast('کپی شد'),()=>prompt('این متن را کپی کن:',t))}catch(e){prompt('این متن را کپی کن:',t)}};
H.errclr=()=>{window.daniErrClear&&window.daniErrClear();render()};

/* ===== DANI v1: calendar export (.ics) - lets the phone's own calendar ring the alarms even when the app is closed ===== */
const icsE=t=>String(t==null?'':t).replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\r?\n/g,'\\n');
function icsFold(l){const enc=new TextEncoder();let out='',cur='',n=0;for(const ch of l){const b=enc.encode(ch).length;if(n+b>73){out+=cur+'\r\n ';cur=ch;n=b}else{cur+=ch;n+=b}}return out+cur}
const icsLoc=(d,t,addMin)=>{const[y,m,x]=d.split('-').map(Number),[h,n]=t.split(':').map(Number),z=new Date(y,m-1,x,h,n+(addMin||0)),p2=v=>String(v).padStart(2,'0');return z.getFullYear()+p2(z.getMonth()+1)+p2(z.getDate())+'T'+p2(z.getHours())+p2(z.getMinutes())+'00'};
const icsTrig=o=>o<=0?'PT0M':'-PT'+(o%60===0?(o/60)+'H':o+'M');
function icsEv(uid,sum,desc,d,t,alarms,rr){const L=['BEGIN:VEVENT','UID:'+uid,'DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').slice(0,15)+'Z','DTSTART:'+icsLoc(d,t,0),'DTEND:'+icsLoc(d,t,30),'SUMMARY:'+icsE(sum)];if(desc)L.push('DESCRIPTION:'+icsE(desc));if(rr)L.push('RRULE:'+rr);(alarms||[]).forEach(o=>L.push('BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+icsE(sum),'TRIGGER:'+icsTrig(o),'END:VALARM'));L.push('END:VEVENT');return L}
function icsBuild(){const L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//DANI Planner//FA','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:DANI'];let nd=0,nr=0;
 try{zDL().items.filter(x=>dlOk(x)&&!x.arch&&!x.done).forEach(x=>{L.push(...icsEv('dani-dl-'+x.id+'@dani.local','موعد: '+x.title,x.note||'',x.dt,x.tm,Array.isArray(x.al)?x.al:[],''));nd++})}catch(e){}
 try{const DAYS=['SU','MO','TU','WE','TH','FR','SA'];rItems().filter(r=>!r.off).forEach(r=>{let rr='';if(r.repeat==='daily')rr='FREQ=DAILY';else if(r.repeat==='weekly')rr='FREQ=WEEKLY'+(Array.isArray(r.days)&&r.days.length?';BYDAY='+r.days.filter(i=>i>=0&&i<=6).map(i=>DAYS[i]).join(','):'');else if(r.repeat==='monthly')rr='FREQ=MONTHLY';L.push(...icsEv('dani-rm-'+r.id+'@dani.local','یادآوری: '+r.title,'',r.date,r.time,rSteps(r),rr));nr++})}catch(e){}
 L.push('END:VCALENDAR');return{text:L.map(icsFold).join('\r\n')+'\r\n',nd,nr}}
H.ics=()=>{const r=icsBuild();if(!r.nd&&!r.nr)return toast('موعد یا یادآور فعالی برای خروجی نیست',1);try{const u=URL.createObjectURL(new Blob([r.text],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='DANI-calendar.ics';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);toast(fa(r.nd)+' موعد و '+fa(r.nr)+' یادآور برای تقویم گوشی ساخته شد')}catch(e){toast('ساخت فایل تقویم ناموفق بود: '+e.message,1)}};
